&lt;div class="crayons-story__indention"&gt;
&lt;h2 class="crayons-story__title crayons-story__title-full_post"&gt;
&lt;a href="https://dev.to/babelize/next-intl-vs-react-i18next-which-react-i18n-library-should-you-use-36mj" id="article-link-4819452"&gt;
next-intl vs react-i18next: Which React i18n Library Should You Use?
&lt;/a&gt;
&lt;/h2&gt;
&lt;div class="crayons-story__tags"&gt;
&lt;a class="crayons-tag  crayons-tag--monochrome " href="/t/nextjs"&gt;&lt;span class="crayons-tag__prefix"&gt;#&lt;/span&gt;nextjs&lt;/a&gt;
&lt;a class="crayons-tag  crayons-tag--monochrome " href="/t/react"&gt;&lt;span class="crayons-tag__prefix"&gt;#&lt;/span&gt;react&lt;/a&gt;
&lt;a class="crayons-tag  crayons-tag--monochrome " href="/t/i18n"&gt;&lt;span class="crayons-tag__prefix"&gt;#&lt;/span&gt;i18n&lt;/a&gt;
&lt;a class="crayons-tag  crayons-tag--monochrome " href="/t/javascript"&gt;&lt;span class="crayons-tag__prefix"&gt;#&lt;/span&gt;javascript&lt;/a&gt;
&lt;/div&gt;
&lt;div class="crayons-story__bottom"&gt;
&lt;div class="crayons-story__details"&gt;
&lt;a href="https://dev.to/babelize/next-intl-vs-react-i18next-which-react-i18n-library-should-you-use-36mj" class="crayons-btn crayons-btn--s crayons-btn--ghost crayons-btn--icon-left"&gt;
&lt;div class="multiple_reactions_aggregate"&gt;
&lt;span class="multiple_reactions_icons_container"&gt;
&lt;span class="crayons_icon_container"&gt;
&lt;img src="https://assets.dev.to/assets/sparkle-heart-5f9bee3767e18deb1bb725290cb151c25234768a0e9a2bd39370c382d02920cf.svg" width="24" height="24"&gt;
&lt;/span&gt;
&lt;/span&gt;
&lt;span class="aggregate_reactions_counter"&gt;4&lt;span class="hidden s:inline"&gt;&amp;nbsp;reactions&lt;/span&gt;&lt;/span&gt;
&lt;/div&gt;
